#[test]
fn test_drawdown_all_negative_small() {
    let mut returns = [0; ARRAY_SIZE];
    for i in 0..5 {
        returns[i] = -1000000;
    }
    let result = daily_max_drawdown(returns, 5);
    let expected = 4877058i64;
    let diff = if result > expected {
        result - expected
    } else {
        expected - result
